input.command:
mkdir -p .claudinite/temp/scan && for f in $(git ls-tree --name-only origin/conversation-logs | grep -E '^2026-09-13'); do git show origin/conversation-logs:$f > .claudinite/temp/scan/$f; done; git show origin/agent-sessions:2026-11-03T1159Z--issue-760--a8028abf-c5da-5acc-963f-a1428adeba15.jsonl > .claudinite/temp/scan/760.jsonl; wc -c .claudinite/temp/scan/*; cat > .claudinite/temp/scan/sum.mjs <<'EOF'
import fs from 'fs';
const f=process.argv[2];
for (const l of fs.readFileSync(f,'utf8').split('\n')){ if(!l)continue; let o; try{o=JSON.parse(l)}catch{continue}
 const m=o.message||o; const c=m.content; const role=m.role||o.type;
 if(typeof c==='string'){ console.log(`[${role}] ${c.slice(0,300).replace(/\n/g,' ')}`); continue;}
 if(!Array.isArray(c))continue;
 for(const b of c){ if(b.type==='text') console.log(`[${role}] ${b.text.slice(0,300).replace(/\n/g,' ')}`);
  else if(b.type==='tool_use') console.log(`  > ${b.name} ${JSON.stringify(b.input).slice(0,120)}`);}
}
EOF
node .claudinite/temp/scan/sum.mjs .claudinite/temp/scan/760.jsonl | head -80

